'use strict';
const {names,factors,status,step}=Convection, ids=Object.keys(names), $=id=>document.getElementById(id);
const homework=id=>id==='btcs'||id==='ftfs';
function integerControl(id,min,max,fallback){const raw=Number($(id).value),value=Number.isFinite(raw)?Math.round(raw):fallback;$(id).value=Math.min(max,Math.max(min,value));return Number($(id).value);}
const info={
 ftbs:{order:'1 / 1',rule:'0 ≤ C ≤ 1',g:'G = 1 − C + C e⁻ⁱᶿ',eq:'uⱼⁿ⁺¹ = uⱼⁿ − C(uⱼⁿ − uⱼ₋₁ⁿ)',desc:'Forward Euler in time, backward difference in space.',proof:'|G|² = 1 − 2C(1 − C)(1 − cosθ)',note:'With positive speed and 0 < C < 1, FTBS damps short waves and smears sharp fronts. At C = 1 it shifts grid values exactly one cell. For negative speed this fixed backward stencil points downwind.'},
 ftcs:{order:'1 / 2',rule:'Unstable for C ≠ 0',g:'G = 1 − iC sinθ',eq:'uⱼⁿ⁺¹ = uⱼⁿ − (C/2)(uⱼ₊₁ⁿ − uⱼ₋₁ⁿ)',desc:'Forward Euler in time, centered difference in space.',proof:'|G|² = 1 + C² sin²θ > 1 for nonzero C and sinθ ≠ 0',note:'Reducing the time step slows the growth but does not make FTCS stable at fixed nonzero C. Try k = N/4: its θ = π/2 mode grows, whereas the checkerboard θ = π has G = 1 and can conceal the instability.'},
 ftfs:{order:'1 / 1',rule:'Determine as homework',g:'Derive as homework',eq:'uⱼⁿ⁺¹ = uⱼⁿ − C(uⱼ₊₁ⁿ − uⱼⁿ)',desc:'Forward Euler in time, forward difference in space.',proof:'Homework: derive G(θ) and determine the stability requirement.',note:'Investigate FTFS. Try both directions of wave travel and several Courant numbers, then derive a stability condition from the update equation. Use numerical observations as evidence, not as a substitute for a proof.'},
 leapfrog:{order:'2 / 2',rule:'|C| < 1 robust; endpoints marginal',g:'G² + 2iC sinθ G − 1 = 0',eq:'uⱼⁿ⁺¹ = uⱼⁿ⁻¹ − C(uⱼ₊₁ⁿ − uⱼ₋₁ⁿ)',desc:'Centered time and centered space. One Lax–Wendroff step supplies the second time level.',proof:'G± = −iC sinθ ± √(1 − C² sin²θ)',note:'Inside |C| < 1 both roots have unit magnitude: waves persist without numerical damping, including a computational time mode. At |C| = 1, repeated roots at θ = π/2 or 3π/2 can cause linear growth for generic two-level data. Above the limit one root grows exponentially.'},
 btcs:{order:'1 / 2',rule:'Determine as homework',g:'Derive as homework',eq:'uⱼⁿ⁺¹ + (C/2)(uⱼ₊₁ⁿ⁺¹ − uⱼ₋₁ⁿ⁺¹) = uⱼⁿ',desc:'Backward Euler in time, centered space at the new time level (BTCS).',proof:'Homework: derive G(θ) from this update and determine the stability condition.',note:'Investigate the implicit method. Vary C, grid size, profile, and Fourier mode; record what you observe. Derive an amplification factor and justify your stability conclusion. A finite experiment alone is not a proof.'},
 lw:{order:'2 / 2',rule:'|C| ≤ 1',g:'G = 1 − iC sinθ + C²(cosθ − 1)',eq:'uⱼⁿ⁺¹ = uⱼⁿ − (C/2)(uⱼ₊₁ⁿ − uⱼ₋₁ⁿ) + (C²/2)(uⱼ₊₁ⁿ − 2uⱼⁿ + uⱼ₋₁ⁿ)',desc:'A Taylor expansion in time with the PDE used to replace time derivatives.',proof:'|G|² = 1 − 4C²(1 − C²)sin⁴(θ/2)',note:'The second-order correction reduces smearing but produces dispersive overshoots near discontinuities. For |C| ≤ 1 these oscillations are bounded; for |C| > 1 short waves amplify.'},
 mac:{order:'2 / 2',rule:'|C| ≤ 1',g:'Same G as Lax–Wendroff',eq:'Predict: u*ⱼ = uⱼⁿ − C(uⱼ₊₁ⁿ − uⱼⁿ) <br>Correct: uⱼⁿ⁺¹ = ½[uⱼⁿ + u*ⱼ − C(u*ⱼ − u*ⱼ₋₁)]',desc:'Forward-space predictor followed by a backward-space corrector.',proof:'|G|² = 1 − 4C²(1 − C²)sin⁴(θ/2)',note:'MacCormack and Lax–Wendroff are algebraically identical here. Their agreement is a useful check, not a general equivalence for nonlinear fluxes or variable coefficients.'}
};
let c=.8,N=80,n=0,dt=.02,running=false,last=0,states={},focus='lw',shape='square',mode=20,eps=1e-10,maxSteps=600;
for(const id of ids){$('focus').add(new Option(names[id],id));const card=document.createElement('article');card.className='plot';card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label','Inspect '+names[id]);card.innerHTML=`<div class="plot-head"><b>${names[id]}</b><span class="badge" id="badge-${id}"></span></div><canvas id="plot-${id}" role="img" aria-label="${names[id]} numerical solution and exact solution"></canvas><div class="plot-stats" id="stats-${id}"></div>`;card.onclick=()=>select(id);card.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();select(id);}};$('plots').appendChild(card);const tr=document.createElement('tr');tr.innerHTML=`<td><button class="text-button">${names[id]}</button></td><td>${info[id].order}</td><td>${info[id].g}</td><td>${info[id].rule}</td><td>${homework(id)?'Investigate as homework':id==='ftcs'?'Error amplification':id==='leapfrog'?'Two time modes':id==='ftbs'?'Numerical damping':'Dispersive ripples'}</td>`;tr.onclick=()=>{select(id);$('analysis').scrollIntoView({behavior:'smooth'});};$('schemeTable').appendChild(tr);}
function profile(x){x=((x%2)+2)%2;if(shape==='square')return x>=.5&&x<1?2:1;if(shape==='step')return x<.5?1:2;if(shape==='sine')return 1.5+.5*Math.sin(Math.PI*x);let d=Math.min(Math.abs(x-.75),2-Math.abs(x-.75));return 1+Math.exp(-((d/.12)**2));}
function select(id){if(!ids.includes(id))return;focus=id;$('focus').value=id;document.querySelectorAll('.plot').forEach((p,j)=>{p.classList.toggle('selected',ids[j]===id);p.setAttribute('aria-pressed',String(ids[j]===id));});$('schemeTitle').textContent=names[id];$('schemeDesc').textContent=info[id].desc;$('formula').innerHTML=info[id].eq+'<br>'+info[id].g+'<br>'+info[id].proof;$('insight').textContent=info[id].note;$('amp-panel').hidden=homework(id);$('homework-analysis').hidden=!homework(id);$('homework-heading').textContent='What stability condition does '+names[id]+' require?';$('growth-description').textContent=homework(id)?'Measured Fourier-mode amplitude only. Use these observations to form and test your own hypothesis.':'Solid: measured Fourier-mode amplitude. Dashed: ερⁿ (a spectral guide for leapfrog, which has two roots).';draw();}
function reset(){running=false;$('play').textContent='▶ Play';c=Number($('cfl-number').value);if(!Number.isFinite(c))c=.8;c=Math.max(-10,Math.min(10,c));$('cfl-number').value=c;$('cfl').value=c;N=integerControl('grid',20,2000,80);maxSteps=integerControl('max-steps',1,10000,600);shape=$('shape').value;mode=Math.max(1,Math.min(Math.floor(N/2),Math.round(Number($('mode').value)||1)));$('mode').value=mode;$('mode').max=Math.floor(N/2);eps=Number($('eps').value);dt=(Math.abs(c)||1)*2/N;n=0;$('cval').textContent=Number(c.toPrecision(4)).toString();states={};for(const id of ids){const u=Float64Array.from({length:N},(_,j)=>profile(2*j/N));const p=Float64Array.from({length:N},(_,j)=>eps*Math.cos(2*Math.PI*mode*j/N));states[id]={u,prev:null,p,pprev:null,h:[eps],frozen:false,pfrozen:false,stoppedAt:null};}draw();}
function amplitude(u){let re=0,im=0;for(let j=0;j<N;j++){const t=2*Math.PI*mode*j/N;re+=u[j]*Math.cos(t);im-=u[j]*Math.sin(t);}return Math.hypot(re,im)/N*(mode===N/2?1:2);}
function advance(){if(n>=maxSteps){running=false;$('play').textContent='▶ Play';return;}for(const id of ids){const s=states[id];if(!s.frozen){const next=step(id,s.u,s.prev,c);s.prev=s.u;s.u=next;s.frozen=next.some(v=>!Number.isFinite(v)||Math.abs(v)>1e6);if(s.frozen)s.stoppedAt=n+1;}if(!s.pfrozen){const p=id==='leapfrog'&&n===0&&$('startup').value==='zero'?new Float64Array(N):step(id,s.p,s.pprev,c);s.pprev=s.p;s.p=p;const amp=amplitude(p);s.h.push(amp);s.pfrozen=!Number.isFinite(amp)||amp>1e12;}}n++;draw();}
// Canvas coordinates are CSS pixels; each frame is scaled for high-density screens.
function chart(id,xmin,xmax,ymin,ymax,xticks,yticks){const canvas=$(id),w=canvas.clientWidth,h=canvas.clientHeight,dpr=window.devicePixelRatio||1;canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const box={l:48,r:w-13,t:12,b:h-27},X=x=>box.l+(x-xmin)/(xmax-xmin)*(box.r-box.l),Y=y=>box.b-(y-ymin)/(ymax-ymin)*(box.b-box.t);ctx.font='10px ui-monospace,monospace';ctx.lineWidth=1;for(const y of yticks){ctx.strokeStyle='#e4e9e4';ctx.beginPath();ctx.moveTo(box.l,Y(y));ctx.lineTo(box.r,Y(y));ctx.stroke();ctx.fillStyle='#728078';ctx.textAlign='right';ctx.fillText(Math.abs(y)>=1e4?y.toExponential(0):Number(y.toPrecision(3)).toString(),box.l-7,Y(y)+3);}for(const x of xticks){ctx.fillStyle='#728078';ctx.textAlign='center';ctx.fillText(Number(x.toPrecision(3)).toString(),X(x),h-8);}return {ctx,X,Y,box,w,h};}
function line(ch,points,color,dash=[]){const {ctx,X,Y,box}=ch;ctx.save();ctx.beginPath();ctx.rect(box.l,box.t,box.r-box.l,box.b-box.t);ctx.clip();ctx.strokeStyle=color;ctx.lineWidth=1.7;ctx.setLineDash(dash);ctx.beginPath();let start=true;for(const [x,y]of points){if(!Number.isFinite(y)){start=true;continue;}if(start){ctx.moveTo(X(x),Y(y));start=false;}else ctx.lineTo(X(x),Y(y));}ctx.stroke();ctx.restore();}
function draw(){if(!states[focus])return;drawConditions();$('nread').textContent=n+(n>=maxSteps?' (limit)':'');$('tread').textContent=(n*dt).toFixed(3);$('dxread').textContent=(2/N).toFixed(4);$('dtread').textContent=dt.toPrecision(4);for(const id of ids){const s=states[id],t=(s.stoppedAt??n)*dt,exact=Array.from({length:401},(_,j)=>[2*j/400,profile(2*j/400-Math.sign(c)*t)]),num=Array.from(s.u,(v,j)=>[2*j/N,v]);num.push([2,s.u[0]]);let lo=Math.min(.7,...s.u),hi=Math.max(2.3,...s.u);if(!Number.isFinite(lo)||!Number.isFinite(hi)){lo=-1e6;hi=1e6;}const pad=(hi-lo)*.08;lo-=pad;hi+=pad;const ch=chart('plot-'+id,0,2,lo,hi,[0,1,2],[lo,(lo+hi)/2,hi]);if($('show-initial').checked)line(ch,Array.from({length:401},(_,j)=>[2*j/400,profile(2*j/400)]),'#8c5d9e',[2,4]);line(ch,exact,'#008678',[4,3]);line(ch,num,'#365acc');const st=status(id,c);$('badge-'+id).className='badge '+st;$('badge-'+id).textContent=st;let err=0;for(let j=0;j<N;j++)err+=Math.abs(s.u[j]-profile(2*j/N-Math.sign(c)*t));$('stats-'+id).textContent=s.frozen?'Frozen at step '+s.stoppedAt+' · |u| > 10⁶':'L₁ / L = '+(err/N).toExponential(2)+' · max |u| = '+Math.max(...s.u.map(Math.abs)).toPrecision(3);}
const st=status(focus,c);$('status').innerHTML=`<span class="badge ${st}">${st} at C = ${Number(c.toPrecision(4))}</span>`;
let rho=null;if(!homework(focus)){const branches=[[],[]];let max=1;rho=Math.max(...factors(focus,c,2*Math.PI*mode/N).map(z=>Math.hypot(...z)));for(let j=0;j<=400;j++){let th=Math.PI*j/400;factors(focus,c,th).forEach((z,k)=>{const g=Math.hypot(...z);branches[k].push([th/Math.PI,g]);max=Math.max(max,g);});}const ac=chart('amp',0,1,0,Math.max(1.25,max*1.12),[0,.25,.5,.75,1],[0,.5,1, ...(max>1.4?[Math.ceil(max)]:[])]);line(ac,[[0,1],[1,1]],'#a8afa8',[5,4]);branches.forEach((b,j)=>line(ac,b,j?'#c66032':'#007d72',j?[4,3]:[]));ac.ctx.fillStyle='#728078';ac.ctx.textAlign='right';ac.ctx.fillText('θ / π',ac.w-13,ac.h-8);$('gain').textContent='maxθ |G| = '+max.toFixed(4)+' · selected mode ρ = '+rho.toFixed(4);}
const h=states[focus].h.map((v,j)=>[j,Math.log10(Math.max(v,1e-300))]);const pred=homework(focus)?[]:Array.from({length:n+1},(_,j)=>[j,Math.log10(eps)+j*Math.log10(Math.max(rho,1e-300))]);const vals=[...h,...pred].map(p=>p[1]).filter(Number.isFinite);const yl=Math.max(-40,Math.min(-18,Math.floor(Math.min(...vals)/4)*4)),yh=Math.max(0,Math.min(20,Math.ceil(Math.max(...vals)/4)*4));const gc=chart('growth',0,Math.max(60,n),yl,yh,[0,Math.round(Math.max(60,n)/2),Math.max(60,n)],[yl,(yl+yh)/2,yh]);line(gc,pred,'#c66032',[5,4]);line(gc,h,'#007d72');gc.ctx.fillStyle='#728078';gc.ctx.textAlign='left';gc.ctx.fillText('log₁₀ amplitude',gc.box.l,10);gc.ctx.textAlign='right';gc.ctx.fillText('step n',gc.w-13,gc.h-8);
}
$('show-initial').onchange=draw;$('cfl').oninput=()=>{$('cfl-number').value=$('cfl').value;reset();};$('cfl-number').onchange=reset;$('max-steps').onchange=()=>{maxSteps=integerControl('max-steps',1,10000,600);if(n>=maxSteps){running=false;$('play').textContent='▶ Play';}draw();};for(const id of ['shape','grid','mode','eps','startup'])$(id).onchange=reset;$('focus').onchange=()=>select($('focus').value);$('step').onclick=()=>{running=false;$('play').textContent='▶ Play';advance();};$('reset').onclick=reset;$('play').onclick=()=>{if(n>=maxSteps)reset();running=!running;$('play').textContent=running?'Ⅱ Pause':'▶ Play';};document.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>{$('cfl-number').value=b.dataset.c;$('startup').value=b.dataset.root?'zero':'lw';if(b.dataset.root)$('mode').value=Number($('grid').value)/4;reset();select(b.dataset.s);});$('download').onclick=()=>{let rows=['x,exact_at_global_time,'+ids.map(id=>id+'_step,'+id).join(',')];for(let j=0;j<N;j++)rows.push([2*j/N,profile(2*j/N-Math.sign(c)*n*dt),...ids.flatMap(id=>[states[id].stoppedAt??n,states[id].u[j]])].join(','));const url=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'})),a=document.createElement('a');a.href=url;a.download='convection-C'+c+'-step'+n+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),500);};window.addEventListener('resize',draw);function animate(t){if(running&&t-last>=1000/Number($('speed').value)){advance();last=t;}requestAnimationFrame(animate);}reset();select('lw');requestAnimationFrame(animate);

function drawConditions(){
 const descriptions={
 square:['Square pulse','u₀(x) = 2 for 0.5 ≤ x < 1; u₀(x) = 1 elsewhere.','Two sharp fronts start at x = 0.5 and x = 1. The initial plateau remains fixed in purple while the exact wave translates in green.'],
 step:['Step with a periodic seam','u₀(x) = 1 for 0 ≤ x < 0.5; u₀(x) = 2 for 0.5 ≤ x < 2.','Periodic repetition adds a second jump at the seam x = 0 ≡ 2. This is a periodic jump pair, not an isolated step on an infinite line.'],
 sine:['Smooth sine wave','u₀(x) = 1.5 + 0.5 sin(πx)','One wavelength fills the domain. The values and derivatives match smoothly at the periodic seam.'],
 gauss:['Periodic Gaussian','u₀(x) = 1 + exp[−(d(x,0.75)/0.12)²]','Here d(x,0.75) = min(|x − 0.75|, 2 − |x − 0.75|) on [0,2). The peak starts at x = 0.75 and wraps around the connected domain.']
 };
 const [title,formula,note]=descriptions[shape],t=n*dt,a=Math.sign(c);
 $('initial-title').textContent=title;$('initial-formula').textContent=formula;$('initial-note').textContent=note;
 const ch=chart('initial-plot',0,2,.8,2.2,[0,.5,1,1.5,2],[1,1.5,2]);
 line(ch,Array.from({length:801},(_,j)=>[j/400,profile(j/400)]),'#8c5d9e');
 line(ch,Array.from({length:801},(_,j)=>[j/400,profile(j/400-a*t)]),'#008678',[5,4]);
 const xraw=.75+a*t,xwrap=((xraw%2)+2)%2;
 $('wave-marker').style.left=(xwrap/2*100)+'%';
 $('wrap-direction').textContent=a>0?'Exit right ↷ re-enter left':a<0?'Exit left ↶ re-enter right':'Zero speed · profile stays still';
 $('characteristic').textContent='Track a point: x₀ = 0.75 → x(t) = (0.75 + at) mod 2 = '+xwrap.toFixed(3)+' at t = '+t.toFixed(3)+'. Boundary crossings: '+Math.abs(Math.floor(xraw/2))+'.';
 const s=states[focus],fmt=v=>Number.isFinite(v)?v.toPrecision(4):String(v);
 $('boundary-scheme').textContent=names[focus]+' · step '+(s.stoppedAt??n);
 $('ghost-left').textContent=$('edge-right').textContent=fmt(s.u[N-1]);
 $('ghost-right').textContent=$('edge-left').textContent=fmt(s.u[0]);
}
